-- @case 1: a store with two address types gives two rows (AddressLine2 NULL on one, '' on the other; trailing space in a city kept); a missing state province, address type or country drops the row
BEGIN;
DELETE FROM person.address;
DELETE FROM person.address_type;
DELETE FROM person.business_entity_address;
DELETE FROM person.country_region;
DELETE FROM person.state_province;
DELETE FROM sales.store;
INSERT INTO person.address ("AddressID", "AddressLine1", "AddressLine2", "City", "StateProvinceID", "PostalCode") VALUES
  ('1', '1 Main St', NULL, 'Bothell', '1', '98001'),
  ('2', '2 Main St', '', 'Seattle ', '1', '98002'),
  ('3', '3 Main St', NULL, 'Nowhere', '99', '98003'),
  ('4', '4 Main St', NULL, 'Redmond', '1', '98004'),
  ('5', '5 Main St', NULL, 'Paris', '3', '98005'),
  ('6', '6 Main St', 'Suite 5', 'Calgary', '2', '98006');
INSERT INTO person.address_type ("AddressTypeID", "Name") VALUES
  ('1', 'Main Office'),
  ('2', 'Shipping');
INSERT INTO person.business_entity_address ("BusinessEntityID", "AddressID", "AddressTypeID") VALUES
  ('1', '1', '1'),
  ('1', '2', '2'),
  ('2', '3', '1'),
  ('3', '4', '9'),
  ('4', '5', '1'),
  ('5', '6', '2');
INSERT INTO person.country_region ("CountryRegionCode", "Name") VALUES
  ('US', 'United States'),
  ('CA', 'Canada');
INSERT INTO person.state_province ("StateProvinceID", "CountryRegionCode", "Name") VALUES
  ('1', 'US', 'Washington'),
  ('2', 'CA', 'Alberta'),
  ('3', 'FR', 'Ile-de-France');
INSERT INTO sales.store ("BusinessEntityID", "Name") VALUES
  ('1', 'store 1'),
  ('2', 'store 2'),
  ('3', 'store 3'),
  ('4', 'store 4'),
  ('5', 'store 5');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM sales.v_store_with_addresses;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['BusinessEntityID', 'Name', 'AddressType', 'AddressLine1', 'AddressLine2', 'City', 'StateProvinceName', 'PostalCode', 'CountryRegionName']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 a store with two address types gives two rows (AddressLine2 NULL on one, on the other; trailing space…', got, ARRAY['BusinessEntityID', 'Name', 'AddressType', 'AddressLine1', 'AddressLine2', 'City', 'StateProvinceName', 'PostalCode', 'CountryRegionName']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', 'store 1', 'Main Office', '1 Main St', NULL, 'Bothell', 'Washington', '98001', 'United States'),
  ('1', 'store 1', 'Shipping', '2 Main St', '', 'Seattle ', 'Washington', '98002', 'United States'),
  ('5', 'store 5', 'Shipping', '6 Main St', 'Suite 5', 'Calgary', 'Alberta', '98006', 'Canada');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 a store with two address types gives two rows (AddressLine2 NULL on one, on the other; trailing space…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;

